{"command": "python3 -c "
import re

bot_count = 0
with open('/workdir/data/access.log') as f:
    for line in f:
        ua_match = re.search(r'\"([^\"]+)\"$', line)  # last quoted string is user agent
        if ua_match:
            ua = ua_match.group(1)
            if 'bot' in ua.lower():
                bot_count += 1
print(f'Bots (containing \"bot\" case-insensitive): {bot_count}')
""}

